251  int flb_parser_logfmt_do(struct flb_parser *parser,
   252                          const char *in_buf, size_t in_size,
   253                          void **out_buf, size_t *out_size,
   254                          struct flb_time *out_time)
   255  {
   256      int ret;
   257      time_t time_lookup;
   258      double tmfrac = 0;
   259      struct flb_time *t;
   260      msgpack_sbuffer tmp_sbuf;
   261      msgpack_packer tmp_pck;
   262      char *dec_out_buf;
   263      size_t dec_out_size;
   264      size_t map_size;
   265      char *time_key;
   266      size_t time_key_len;
   267      int last_byte;
   268
   269      if (parser->time_key) {
   270          time_key = parser->time_key;
   271      }
   272      else {
   273          time_key = "time";
   274      }
   275      time_key_len = strlen(time_key);
   276      time_lookup = time(NULL);
   277
   278      /* count the number of key value pairs */
   279      map_size = 0;
   280      logfmt_parser(parser, in_buf, in_size, NULL,
   281                    time_key, time_key_len,
   282                    &time_lookup, &tmfrac, &map_size);
   283      if (map_size == 0) {
   284          return -1;
   285      }
   286
   287      /* Prepare new outgoing buffer */
   288      msgpack_sbuffer_init(&tmp_sbuf);
   289      msgpack_packer_init(&tmp_pck, &tmp_sbuf, msgpack_sbuffer_write);
   290      msgpack_pack_map(&tmp_pck, map_size);
   291
   292      last_byte = logfmt_parser(parser, in_buf, in_size, &tmp_pck,
   293                                time_key, time_key_len,
   294                                &time_lookup, &tmfrac, &map_size);
   295      if (last_byte < 0) {
   296          msgpack_sbuffer_destroy(&tmp_sbuf);
   297          return last_byte;
   298      }
   299
   300      /* Export results */
   301      *out_buf = tmp_sbuf.data;
   302      *out_size = tmp_sbuf.size;
   303
   304      t = out_time;
   305      t->tm.tv_sec  = time_lookup;
   306      t->tm.tv_nsec = (tmfrac * 1000000000);
   307
   308      /* Check if some decoder was specified */
   309      if (parser->decoders) {
   310          ret = flb_parser_decoder_do(parser->decoders,
   311                                      tmp_sbuf.data, tmp_sbuf.size,
   312                                      &dec_out_buf, &dec_out_size);
   313          if (ret == 0) {
   314              *out_buf = dec_out_buf;
   315              *out_size = dec_out_size;
   316              msgpack_sbuffer_destroy(&tmp_sbuf);
   317          }
   318      }
   319
   320      return last_byte;
   321  }
